package hexadecimal

import (
	"errors"
	"fmt"
)

// ParseHex converts a hexadecimal string to its decimal equivalent.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, errors.New("syntax error: empty string")
	}

	var result int64
	for _, c := range in {
		var digit int64
		switch {
		case c >= '0' && c <= '9':
			digit = int64(c - '0')
		case c >= 'a' && c <= 'f':
			digit = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid hex character %q", c)
		}

		if result > (math.MaxInt64-digit)/16 {
			return 0, errors.New("range error: value out of range")
		}
		result = result*16 + digit
	}

	return result, nil
}
```

