package hexadecimal

import (
	"errors"
	"fmt"
	"math"
)

// Sentinel errors returned by ParseHex.
var (
	// ErrSyntax is returned when the input is not a valid hexadecimal string.
	ErrSyntax = errors.New("syntax error")
	// ErrRange is returned when the value does not fit in an int64.
	ErrRange = errors.New("range error")
)

// ParseHex converts a hexadecimal string, e.g. "10af8c", to its decimal
// equivalent. It returns ErrSyntax if the input contains invalid characters
// (including the empty string) and ErrRange if the value overflows int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, ErrSyntax
	}

	var result int64
	for _, c := range in {
		var digit int64
		switch {
		case c >= '0' && c <= '9':
			digit = int64(c - '0')
		case c >= 'a' && c <= 'f':
			digit = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("%w: invalid hex character %q", ErrSyntax, c)
		}

		// Overflow check: result*16+digit must not exceed math.MaxInt64.
		if result > (math.MaxInt64-digit)/16 {
			return 0, ErrRange
		}
		result = result*16 + digit
	}

	return result, nil
}

// HandleErrors calls ParseHex on each input and reports "none", "syntax",
// or "range" for each result.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case errors.Is(err, ErrRange):
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}
